				j++
			}
			if j >= n {
				// Unterminated — drop the rest.
				return out.String()
			}
			i = j + 1
			continue
		}

		// $(...) command substitution: skip nested parens (depth-aware).
		if c == '$' && i+1 < n && input[i+1] == '(' {
			i = skipDollarParen(input, i)
			continue
		}

		// Heredoc opened at the shell skeleton level.
		if c == '<' && i+1 < n && input[i+1] == '<' {
			if end, ok := skipHeredoc(input, i); ok {
