	// (.md, .mdx, .json, .yaml, .yml, .toml, .lock, .env).
	ClassDoc PathClass = "doc"

	// ClassUnknown is the fall-through when the path has no extension
	// and matches none of the above.
	ClassUnknown PathClass = "unknown"
)

