	out.Grow(len(input))
	i := 0
	n := len(input)
	for i < n {
		c := input[i]

		// Single-quoted: literal until next ' (no escapes).
		if c == '\'' {
			end := strings.IndexByte(input[i+1:], '\'')
			if end < 0 {
				return out.String()
			}
			i = i + 1 + end + 1
			continue
		}

